const assert = require('node:assert/strict');
const { once } = require('node:events');
const express = require('express');
const app = require('./solution.cjs')(express);
assert.equal(typeof app, 'function', 'setup must return an Express application');
(async () => {
  const server = app.listen(0, '127.0.0.1');
  try {
    await once(server, 'listening');
    const address = server.address();
    assert.ok(address && Number.isInteger(address.port), 'Server not listening');
    const origin = 'http://127.0.0.1:' + address.port;
    {
      const response = await fetch(origin + "/", {method: "GET", signal: AbortSignal.timeout(5000)});
      assert.equal(response.status, 200, "GET" + ' ' + "/");

    }
    {
      const response = await fetch(origin + "/nested/resource", {method: "GET", signal: AbortSignal.timeout(5000)});
      assert.equal(response.status, 200, "GET" + ' ' + "/nested/resource");

    }
    console.log('PASS wildcard 4.21.2: live HTTP behavior');
  } finally {
    server.close();
  }
})().catch(error => { console.error(error); process.exitCode = 1; });

