      assert.equal(response.status, 404, "GET" + ' ' + "/unmatched");

    }
    {
      const response = await fetch(origin + "/health", {method: "POST", signal: AbortSignal.timeout(5000)});
      assert.equal(response.status, 404, "POST" + ' ' + "/health");

    }
    console.log('PASS stable GET /health 4.21.2: live HTTP behavior');
  } finally {
    server.close();
  }
})().catch(error => { console.error(error); process.exitCode = 1; });

