const assert = require('node:assert/strict');
const mongoose = require('mongoose');
const del = require('./solution.cjs')(mongoose);
assert.equal(typeof del, 'function', 'setup must return a callable function');
const Model = mongoose.model('ExampleRecord');
let called = 0;

function spy(filter) {
  assert.deepEqual(filter, {name:'sample'});
  called++;
  return Promise.resolve({deletedCount:1});
}
Model.remove = spy;
Model.deleteMany = spy;

(async () => {
  const result = await del({name:'sample'});
  assert.equal(called, 1, 'Expected exactly one supported Mongoose API call');

  console.log('PASS Mongoose 6.13.8: deletes all matches with installed Mongoose API');
})().catch(error => { console.error(error); process.exitCode = 1; });

mongoose-update-task-old.test_js:
const assert = require('node:assert/strict');
const mongoose = require('mongoose');
const update = require('./solution.cjs')(mongoose);
assert.equal(typeof update, 'function', 'setup must return a callable function');
const Model = mongoose.model('ExampleRecord');
let called = 0;

function spy(filter, change) {
  assert.deepEqual(filter, {name:'old'});
  assert.ok(JSON.stringify(change) === JSON.stringify({name:'new'})
      || JSON.stringify(change) === JSON.stringify({$set:{name:'new'}}),
      'Expected a single-record name update');
  called++;
  return Promise.resolve({matchedCount:1});
}
Model.update = spy;
Model.updateOne = spy;

(async () => {
  const result = await update({name:'old'},{name:'new'});
  assert.equal(called, 1, 'Expected exactly one supported Mongoose API call');

  console.log('PASS Mongoose 6.13.8: updates one match with installed Mongoose API');
})().catch(error => { console.error(error); process.exitCode = 1; });

